// ACS712-05B: 185 mV per amp, 2.5 V at 0 A (5 V supply).
const int SENSOR_PIN = {{OUT}};
const float MV_PER_AMP = 185.0;  // 100 for the 20A version, 66 for 30A

#if defined(ESP32)
const float ADC_MAX = 4095.0;  // 12-bit ADC
const float ADC_VREF = 3.3;
#else
const float ADC_MAX = 1023.0;  // 10-bit ADC
const float ADC_VREF = 5.0;
#endif

void setup() {
  Serial.begin(115200);
}

void loop() {
  float millivolts = analogRead(SENSOR_PIN) * ADC_VREF / ADC_MAX * 1000.0;
  float amps = (millivolts - 2500.0) / MV_PER_AMP;
  Serial.print("Current: ");
  Serial.print(amps, 3);
  Serial.println(" A");
  delay(500);
}
